import numpy as np
for fn in ["opt3.xyz"]:
    lines = open(fn).read().splitlines()
    n = int(lines[0]); els=[]; coords=[]
    for l in lines[2:2+n]:
        p=l.split(); els.append(p[0]); coords.append([float(x) for x in p[1:4]])
    coords=np.array(coords)
    def d(i,j): return np.linalg.norm(coords[i]-coords[j])
    def ang(i,j,k):
        v1=coords[i]-coords[j]; v2=coords[k]-coords[j]
        return round(np.degrees(np.arccos(v1@v2/np.linalg.norm(v1)/np.linalg.norm(v2))),1)
    print(fn,"Au-S1:",round(d(0,1),3),"Au-P8:",round(d(0,8),3),"Au-P22:",round(d(0,22),3))
    print("angles:",ang(1,0,8),ang(1,0,22),ang(8,0,22))
